@@ -0,0 +1,99 @@
+import type Anthropic from "@anthropic-ai/sdk";
+import { afterEach, describe, expect, setSystemTime, test } from "bun:test";
+import type { AgentRows, SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+
+const THINKING: SignedBlock = { type: "thinking", thinking: "plan the answer", signature: "sig-1" };
+const REDACTED: SignedBlock = { type: "redacted_thinking", data: "blob-1" };
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: { input_tokens: 3, output_tokens: 7, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 } };
+/** A thinking block, a redacted thinking block that yields no chunk, a long text block, and a tool call. */
+const TEXT_CHUNKS = 50;
+const ITEMS: readonly HostStepItem[] = [
+  { kind: "thinking", index: 0, text: "plan " },
+  { kind: "thinking", index: 0, text: "the answer" },
+  ...Array.from({ length: TEXT_CHUNKS }, (_, n): HostStepItem => ({ kind: "text", index: 2, text: `word${n} ` })),
+  { kind: "tool", index: 3, id: "toolu_1", name: "read" },
+  { kind: "input", index: 3, json: "{\"path\":\"a\"}" },
+  STOP,
+];
+
+/** The engine holds a response's rows until the response's stop reason is known, so they land only once the stream
+ *  read the stop chunk. */
+function rowsAfterStop(signed: readonly SignedBlock[]): { rows: AgentRows; steps: (items: readonly HostStepItem[], end?: "done") => AsyncIterable<StepEvent> } {
+  let stopped = false;
+  return {
+    rows: { read: () => (stopped ? signed : []) },
+    async *steps(items, end) {
+      for (const item of items) {
+        if (item.kind === "stop") stopped = true;
+        yield { kind: "item", item };
+      }
+      if (end === "done") yield { kind: "done" };
+    },
+  };
+}
+
+async function collect(events: AsyncIterable<Anthropic.RawMessageStreamEvent>): Promise<Anthropic.RawMessageStreamEvent[]> {
+  const out: Anthropic.RawMessageStreamEvent[] = [];
+  for await (const event of events) out.push(event);
+  return out;
+}
+
+/** The events in a comparable form: the type, the block index, and the delta or block type. */
+function shape(event: Anthropic.RawMessageStreamEvent): string {
+  if (event.type === "content_block_start") return `start ${event.index} ${event.content_block.type}`;
+  if (event.type === "content_block_delta") return `delta ${event.index} ${event.delta.type}`;
+  if (event.type === "content_block_stop") return `stop ${event.index}`;
+  return event.type;
+}
+
+const noFailure = async (): Promise<Error> => new Error("the step ended without its stop chunk");
+
+afterEach(() => { setSystemTime(); });
+
+describe("the hosted step's Anthropic stream", () => {
+  test("a response that writes long after its thinking streams completely in Anthropic event order once the engine writes its rows, and reports each chunk it holds back as progress", async () => {
+    const { rows, steps } = rowsAfterStop([THINKING, REDACTED]);
+    let answer: HostedAnswer | undefined;
+    let progress = 0;
+    const events = await collect(hostedStreamEvents(steps(ITEMS), rows, 0, "claude-test", noFailure, (ended) => { answer = ended; }, () => { progress += 1; }));
+
+    expect(events.map(shape)).toEqual([
+      "message_start",
+      "start 0 thinking", "delta 0 thinking_delta", "delta 0 thinking_delta", "delta 0 signature_delta", "stop 0",
+      "start 1 redacted_thinking", "stop 1",
+      "start 2 text", ...Array.from({ length: TEXT_CHUNKS }, () => "delta 2 text_delta"), "stop 2",
+      "start 3 tool_use", "delta 3 input_json_delta", "stop 3",
+      "message_delta", "message_stop",
+    ]);
+    expect(events).toContainEqual({ type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "sig-1" } });
+    expect(events).toContainEqual({ type: "content_block_start", index: 1, content_block: { type: "redacted_thinking", data: "blob-1" } });
+    expect(answer?.message.content).toEqual([THINKING, REDACTED, { type: "text", text: Array.from({ length: TEXT_CHUNKS }, (_, n) => `word${n} `).join("") }, { type: "tool_use", id: "toolu_1", name: "read", input: { path: "a" } }]);
+    expect(answer?.stopReason).toBe("end_turn");
+    // Every chunk after the thinking block waited behind its row, and the stop chunk found the rows written.
+    expect(progress).toBe(TEXT_CHUNKS + 2);
+  });
+
+  test("a signed row that is still missing after the step's stop chunk fails transient with \"wrote no row\"", async () => {
+    // Each read of the agent file moves the clock a second, so the bound passes without real waiting.
+    const rows: AgentRows = { read: () => { setSystemTime(new Date(Date.now() + 1_000)); return []; } };
+    const { steps } = rowsAfterStop([]);
+    let answered = false;
+    const error = await collect(hostedStreamEvents(steps(ITEMS), rows, 0, "claude-test", noFailure, () => { answered = true; }, () => {})).then(() => undefined, (thrown: unknown) => thrown);
+
+    expect(error).toBeInstanceOf(LlmStreamError);
+    expect((error as LlmStreamError).kind).toBe("transient");
+    expect((error as LlmStreamError).message).toContain("wrote no row");
+    expect(answered).toBe(false);
+  });
+
+  test("a step that ends without its stop chunk fails with the service's answer", async () => {
+    const { rows, steps } = rowsAfterStop([THINKING]);
+    const serviceAnswer = new Error("529 overloaded");
+    const error = await collect(hostedStreamEvents(steps(ITEMS.slice(0, 3), "done"), rows, 0, "claude-test", async () => serviceAnswer, () => {}, () => {})).then(() => undefined, (thrown: unknown) => thrown);
+
+    expect(error).toBe(serviceAnswer);
+  });
+});

