+use react::*;
+use std::cell::Cell;
+
+#[test]
+fn input_and_compute_values_propagate() {
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    let plus_one = r
+        .create_compute(&[CellId::Input(input)], |v| v[0] + 1)
+        .unwrap();
+    let sum = r
+        .create_compute(
+            &[CellId::Input(input), CellId::Compute(plus_one)],
+            |v| v[0] * 10 + v[1],
+        )
+        .unwrap();
+    assert_eq!(r.value(CellId::Compute(sum)), Some(12));
+    assert!(r.set_value(input, 3));
+    assert_eq!(r.value(CellId::Input(input)), Some(3));
+    assert_eq!(r.value(CellId::Compute(plus_one)), Some(4));
+    assert_eq!(r.value(CellId::Compute(sum)), Some(34));
+}
+
+#[test]
+fn nonexistent_cells_are_rejected() {
+    let mut dummy = Reactor::new();
+    let _ = dummy.create_input(0);
+    let missing = dummy.create_input(0);
+    let missing_compute = dummy.create_compute(&[], |_| 0).unwrap();
+
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    assert_eq!(
+        r.create_compute(&[CellId::Input(input), CellId::Input(missing)], |_| 0),
+        Err(CellId::Input(missing))
+    );
+    assert_eq!(r.value(CellId::Input(missing)), None);
+    assert!(!r.set_value(missing, 5));
+    assert!(r.add_callback(missing_compute, |_: i32| ()).is_none());
+    assert_eq!(r.value(CellId::Input(input)), Some(1));
+}
+
+#[test]
+fn callbacks_fire_once_per_changed_stable_state() {
+    let calls = Cell::new(0);
+    let last = Cell::new(0);
+    let silent = Cell::new(0);
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    let a = r.create_compute(&[CellId::Input(input)], |v| v[0] + 1).unwrap();
+    let b = r.create_compute(&[CellId::Input(input)], |v| v[0] - 1).unwrap();
+    let both = r
+        .create_compute(&[CellId::Compute(a), CellId::Compute(b)], |v| v[0] * v[1])
+        .unwrap();
+    let constant = r
+        .create_compute(&[CellId::Compute(a), CellId::Compute(b)], |v| v[0] - v[1])
+        .unwrap();
+    r.add_callback(both, |v| {
+        calls.set(calls.get() + 1);
+        last.set(v);
+    })
+    .unwrap();
+    r.add_callback(constant, |_| silent.set(silent.get() + 1)).unwrap();
+
+    r.set_value(input, 4);
+    r.set_value(input, 4);
+    drop(r);
+    assert_eq!(calls.get(), 1);
+    assert_eq!(last.get(), 15);
+    assert_eq!(silent.get(), 0);
+}
+
+#[test]
+fn removed_callbacks_stop_and_cannot_be_removed_twice() {
+    let first = Cell::new(0);
+    let second = Cell::new(0);
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    let out = r.create_compute(&[CellId::Input(input)], |v| v[0]).unwrap();
+    let cb1 = r.add_callback(out, |_| first.set(first.get() + 1)).unwrap();
+    let _cb2 = r.add_callback(out, |_| second.set(second.get() + 1)).unwrap();
+    assert_eq!(r.remove_callback(out, cb1), Ok(()));
+    assert_eq!(
+        r.remove_callback(out, cb1),
+        Err(RemoveCallbackError::NonexistentCallback)
+    );
+    let mut other = Reactor::<i32>::new();
+    assert_eq!(
+        other.remove_callback(out, cb1),
+        Err(RemoveCallbackError::NonexistentCell)
+    );
+    r.set_value(input, 2);
+    drop(r);
+    assert_eq!(first.get(), 0);
+    assert_eq!(second.get(), 1);
