+import { parse, type TemplateNode } from "./parser.js";
 import { tokenize } from "./tokenizer.js";
 import type { TemplateContext } from "./types.js";

-export function render(template: string, _context: TemplateContext = {}): string {
-  return tokenize(template)
-    .map((token) => token.kind === "text" ? token.value : "")
-    .join("");
+function escapeHtml(value: string): string {
+  return value
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function resolvePath(context: unknown, path: string): unknown {
+  if (path === ".") {
+    return context;
+  }
+
+  let current: unknown = context;
+  for (const segment of path.split(".")) {
+    if (
+      current === null ||
+      current === undefined ||
+      typeof current !== "object" ||
+      !Object.prototype.hasOwnProperty.call(current, segment)
+    ) {
+      return undefined;
+    }
+    current = (current as Record<string, unknown>)[segment];
+  }
+  return current;
+}
+
+function formatValue(value: unknown, escaped: boolean): string {
+  if (value === null || value === undefined) {
+    return "";
+  }
+  const text = String(value);
+  return escaped ? escapeHtml(text) : text;
+}
+
+function renderNodes(nodes: readonly TemplateNode[], context: unknown): string {
+  let output = "";
+  for (const node of nodes) {
+    switch (node.kind) {
+      case "text":
+        output += node.value;
+        break;
+      case "variable":
+        output += formatValue(resolvePath(context, node.path), node.escaped);
+        break;
+      case "block": {
+        const value = resolvePath(context, node.path);
+        if (node.block === "if") {
+          if (value) {
+            output += renderNodes(node.body, context);
+          }
+        } else if (Array.isArray(value)) {
+          for (const item of value) {
+            output += renderNodes(node.body, item);
+          }
+        }
+        break;
+      }
+    }
+  }
+  return output;
+}
+
+export function render(template: string, context: TemplateContext = {}): string {
+  const tokens = tokenize(template);
+  const nodes = parse(tokens);
+  return renderNodes(nodes, context);
 }
