@@ -0,0 +1,53 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+type OpenToken = Extract<TemplateToken, { kind: "open" }>;
+
+export type BlockNode = Omit<OpenToken, "kind"> & { kind: "block"; children: TemplateNode[] };
+
+export type TemplateNode = Extract<TemplateToken, { kind: "text" | "variable" }> | BlockNode;
+
+/**
+ * Builds the nested node tree from a token stream.
+ * Each closing tag matches the innermost open block.
+ * Throws TemplateError at the closing tag's position for an unexpected or mismatched close,
+ * and at the opening tag's position for the innermost block left unclosed.
+ */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const open: BlockNode[] = [];
+
+  for (const token of tokens) {
+    const siblings = open.at(-1)?.children ?? root;
+    switch (token.kind) {
+      case "text":
+      case "variable":
+        siblings.push(token);
+        break;
+      case "open": {
+        const node: BlockNode = { ...token, kind: "block", children: [] };
+        siblings.push(node);
+        open.push(node);
+        break;
+      }
+      case "close": {
+        const innermost = open.pop();
+        if (innermost === undefined) {
+          throw new TemplateError(`Unexpected closing {{/${token.block}}}`, token.position);
+        }
+        if (innermost.block !== token.block) {
+          throw new TemplateError(
+            `Closing {{/${token.block}}} does not match open {{#${innermost.block}}}`,
+            token.position,
+          );
+        }
+        break;
+      }
+    }
+  }
+
+  const unclosed = open.at(-1);
+  if (unclosed !== undefined) {
+    throw new TemplateError(`Unclosed {{#${unclosed.block}}}`, unclosed.position);
+  }
+  return root;
+}
