+/**
+ * Renders a template against a context.
+ * `{{path}}` inserts an HTML-escaped value and `{{{path}}}` inserts it raw; dot paths resolve
+ * from the current scope, a leading `this` names the scope itself, and missing or nullish values
+ * render as empty text. `{{#if path}}` uses JavaScript truthiness; `{{#each path}}` repeats its
+ * body once per array item with that item as the scope, and renders nothing for non-arrays.
+ * Throws TemplateError for malformed tags and unbalanced blocks.
+ */
+export function render(template: string, context: TemplateContext = {}): string {
+  return renderNodes(parse(tokenize(template)), context);
+}
+
+function renderNodes(nodes: readonly TemplateNode[], scope: unknown): string {
+  return nodes.map((node) => renderNode(node, scope)).join("");
+}
+
+function renderNode(node: TemplateNode, scope: unknown): string {
+  switch (node.kind) {
+    case "text":
+      return node.value;
+    case "variable": {
+      const value = resolve(scope, node.path);
+      const text = value === null || value === undefined ? "" : String(value);
+      return node.escaped ? escapeHtml(text) : text;
+    }
+    case "block": {
+      const value = resolve(scope, node.path);
+      if (node.block === "if") {
+        return value ? renderNodes(node.children, scope) : "";
+      }
+      return Array.isArray(value)
+        ? value.map((item) => renderNodes(node.children, item)).join("")
+        : "";
+    }
+  }
+}
+
+function resolve(scope: unknown, path: string): unknown {
+  const segments = path.split(".");
+  if (segments[0] === "this") {
+    segments.shift();
+  }
+  let value = scope;
+  for (const segment of segments) {
+    if (value === null || value === undefined) {
+      return undefined;
+    }
+    value = (value as Record<string, unknown>)[segment];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
 }
