@@ -0,0 +1,77 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string; position: number }
+  | { kind: "variable"; path: string; escaped: boolean; position: number }
+  | {
+      kind: "block";
+      block: "if" | "each";
+      path: string;
+      position: number;
+      children: TemplateNode[];
+    };
+
+interface OpenFrame {
+  readonly block: "if" | "each";
+  readonly path: string;
+  readonly position: number;
+  readonly children: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenFrame[] = [];
+
+  const currentChildren = (): TemplateNode[] =>
+    stack.length > 0 ? stack[stack.length - 1]!.children : root;
+
+  for (const token of tokens) {
+    if (token.kind === "text" || token.kind === "variable") {
+      currentChildren().push(token);
+      continue;
+    }
+
+    if (token.kind === "open") {
+      stack.push({
+        block: token.block,
+        path: token.path,
+        position: token.position,
+        children: [],
+      });
+      continue;
+    }
+
+    const top = stack.pop();
+    if (top === undefined) {
+      throw new TemplateError(
+        `Unexpected closing tag {{/${token.block}}}`,
+        token.position,
+      );
+    }
+
+    if (top.block !== token.block) {
+      throw new TemplateError(
+        `Mismatched closing tag {{/${token.block}}}, expected {{/${top.block}}}`,
+        token.position,
+      );
+    }
+
+    currentChildren().push({
+      kind: "block",
+      block: top.block,
+      path: top.path,
+      position: top.position,
+      children: top.children,
+    });
+  }
+
+  if (stack.length > 0) {
+    const unclosed = stack[stack.length - 1]!;
+    throw new TemplateError(
+      `Unclosed {{#${unclosed.block}}} block`,
+      unclosed.position,
+    );
+  }
+
+  return root;
+}
