+
+describe("render variables and escaping", () => {
+  test("resolves nested dot paths and renders missing or nullish values as empty text", () => {
+    const template = "{{user.profile.name}}|{{user.missing}}|{{user.profile.bio}}|{{absent.deep}}";
+    expect(
