+        user: { profile: { name: "Ada", bio: null } },
+      }),
+    ).toBe("Ada|||");
+  });
+
+  test("renders false and zero as strings", () => {
+    expect(render("{{flag}}:{{count}}", { flag: false, count: 0 })).toBe("false:0");
+  });
+
+  test("escapes &, <, >, double quote, and single quote without double escaping while keeping raw output unchanged", () => {
+    const html = `<a href="x" data-q='y'>a & b</a>`;
+    expect(render("{{content}}", { content: html })).toBe(
+      "&lt;a href=&quot;x&quot; data-q=&#39;y&#39;&gt;a &amp; b&lt;/a&gt;",
+    );
+    expect(render("{{{content}}}", { content: html })).toBe(html);
+  });
+});
+
+describe("render blocks and nesting", () => {
+  test("renders if blocks using ordinary JavaScript truthiness", () => {
+    expect(render("{{#if val}}yes{{/if}}", { val: true })).toBe("yes");
+    expect(render("{{#if val}}yes{{/if}}", { val: [] })).toBe("yes");
+    expect(render("{{#if val}}yes{{/if}}", { val: false })).toBe("");
+    expect(render("{{#if val}}yes{{/if}}", { val: 0 })).toBe("");
+    expect(render("{{#if val}}yes{{/if}}", { val: "" })).toBe("");
+    expect(render("{{#if val}}yes{{/if}}", { val: null })).toBe("");
+    expect(render("{{#if val}}yes{{/if}}", {})).toBe("");
+  });
+
+  test("does not evaluate bodies omitted by a falsy parent if", () => {
+    let accessed = false;
+    const context = {
+      show: false,
+      get secret() {
+        accessed = true;
+        return "hidden";
+      },
+    };
+    expect(render("{{#if show}}{{secret}}{{/if}}", context)).toBe("");
+    expect(accessed).toBe(false);
+  });
+
+  test("renders each blocks only for non-empty arrays with item-scoped context", () => {
+    expect(
+      render("{{#each items}}[{{name}}{{outer}}]{{/each}}", {
+        outer: "X",
+        items: [{ name: "a" }, { name: "b" }],
+      }),
+    ).toBe("[a][b]");
+    expect(render("{{#each items}}x{{/each}}", { items: [] })).toBe("");
+    expect(render("{{#each items}}x{{/each}}", {})).toBe("");
+    expect(render("{{#each items}}x{{/each}}", { items: "not-array" })).toBe("");
+    expect(render("{{#each items}}x{{/each}}", { items: { length: 2 } })).toBe("");
+  });
+
+  test("supports arbitrary mixed and same-kind nesting", () => {
+    const template =
+      "{{#if visible}}{{#if ready}}{{#each groups}}{{title}}:{{#each members}}{{#if active}}{{name}},{{/if}}{{/each}};{{/each}}{{/if}}{{/if}}";
+    const result = render(template, {
+      visible: true,
+      ready: 1,
+      groups: [
+        {
+          title: "G1",
+          members: [
+            { name: "Ann", active: true },
+            { name: "Bob", active: false },
+          ],
+        },
+        {
+          title: "G2",
+          members: [{ name: "Cam", active: true }],
+        },
+      ],
+    });
+    expect(result).toBe("G1:Ann,;G2:Cam,;");
+  });
+
+  test("propagates structural TemplateError positions through render()", () => {
+    const cases: Array<{ template: string; expectedPosition: number }> = [
+      { template: "ok {{/each}}", expectedPosition: 3 },
+      { template: "{{#each a}}{{#if b}}{{/each}}{{/if}}", expectedPosition: 20 },
+      { template: "start {{#each items}}{{name}}", expectedPosition: 6 },
+    ];
+
+    for (const { template, expectedPosition } of cases) {
+      let caught: unknown;
+      try {
+        render(template, { a: [], b: true, items: [] });
+      } catch (error) {
+        caught = error;
+      }
+      expect(caught).toBeInstanceOf(TemplateError);
+      expect((caught as TemplateError).position).toBe(expectedPosition);
+    }
   });
 });
