 import type { TemplateToken } from "./types.js";

+const OPEN_BLOCK_PATTERN = /^#(if|each)\s+([\s\S]+)$/;
+
+function parseDoubleBraceTag(rawContent: string, position: number): TemplateToken {
+  const content = rawContent.trim();
+
+  if (content === "/if") {
+    return { kind: "close", block: "if", position };
+  }
+  if (content === "/each") {
+    return { kind: "close", block: "each", position };
+  }
+
+  const openMatch = OPEN_BLOCK_PATTERN.exec(content);
+  if (openMatch !== null) {
+    return {
+      kind: "open",
+      block: openMatch[1] as "if" | "each",
+      path: openMatch[2]!,
+      position,
+    };
+  }
+
+  return { kind: "variable", path: content, escaped: true, position };
+}
+
 export function tokenize(template: string): TemplateToken[] {
-  return template.length === 0
-    ? []
-    : [{ kind: "text", value: template, position: 0 }];
+  const tokens: TemplateToken[] = [];
+  let cursor = 0;
+  let textStart = 0;
+
+  while (cursor < template.length) {
+    const openPos = template.indexOf("{{", cursor);
+    if (openPos === -1) {
+      break;
+    }
+
+    if (template.startsWith("{{{", openPos)) {
+      const closePos = template.indexOf("}}}", openPos + 3);
+      if (closePos === -1) {
+        cursor = openPos + 1;
+        continue;
+      }
+      if (openPos > textStart) {
+        tokens.push({
+          kind: "text",
+          value: template.slice(textStart, openPos),
+          position: textStart,
+        });
+      }
+      tokens.push({
+        kind: "variable",
+        path: template.slice(openPos + 3, closePos).trim(),
+        escaped: false,
+        position: openPos,
+      });
+      cursor = closePos + 3;
+      textStart = cursor;
+      continue;
+    }
+
+    const closePos = template.indexOf("}}", openPos + 2);
+    if (closePos === -1) {
+      break;
+    }
+
+    if (openPos > textStart) {
+      tokens.push({
+        kind: "text",
+        value: template.slice(textStart, openPos),
+        position: textStart,
+      });
+    }
+    tokens.push(parseDoubleBraceTag(template.slice(openPos + 2, closePos), openPos));
+    cursor = closePos + 2;
+    textStart = cursor;
+  }
+
+  if (textStart < template.length) {
+    tokens.push({
+      kind: "text",
+      value: template.slice(textStart),
+      position: textStart,
+    });
+  }
+
+  return tokens;
